  function sanitizeRichHTML(html){const parsed=new DOMParser().parseFromString(String(html||''),'text/html');const allowed=new Set(['P','DIV','BR','H1','H2','H3','B','STRONG','I','EM','U','S','STRIKE','UL','OL','LI','BLOCKQUOTE','A','TABLE','THEAD','TBODY','TR','TD','TH','SPAN','IMG']);const safeStyle=value=>{const styles=[];for(const declaration of String(value||'').split(';')){const [rawProp,...rest]=declaration.split(':');const prop=rawProp?.trim().toLowerCase(),val=rest.join(':').trim();if(!prop||!val)continue;if(prop==='color'||prop==='background-color'){if(/^(#[0-9a-f]{3,8}|rgb\([\d\s,.%]+\)|rgba\([\d\s,.%]+\)|[a-z]{1,20})$/i.test(val))styles.push(`${prop}:${val}`);}else if(prop==='font-family'&&/^[a-z0-9 ,"'-]{1,80}$/i.test(val))styles.push(`${prop}:${val}`);else if(prop==='font-size'&&/^(\d+(\.\d+)?(px|pt|em|rem|%))$/i.test(val))styles.push(`${prop}:${val}`);else if(prop==='text-align'&&/^(left|center|right|justify)$/i.test(val))styles.push(`${prop}:${val}`);}return styles.join(';');};const cleanNode=node=>{if(node.nodeType===Node.TEXT_NODE)return document.createTextNode(node.textContent);if(node.nodeType!==Node.ELEMENT_NODE)return document.createDocumentFragment();if(node.tagName==='FONT'){const el=document.createElement('span');const styles=[];const color=node.getAttribute('color');const face=node.getAttribute('face');if(color&&/^#[0-9a-f]{3,8}$/i.test(color))styles.push(`color:${color}`);if(face&&/^[a-z0-9 ,"'-]{1,80}$/i.test(face))styles.push(`font-family:${face}`);if(styles.length)el.setAttribute('style',styles.join(';'));[...node.childNodes].forEach(child=>el.append(cleanNode(child)));return el;}if(!allowed.has(node.tagName)){const fragment=document.createDocumentFragment();[...node.childNodes].forEach(child=>fragment.append(cleanNode(child)));return fragment;}const el=document.createElement(node.tagName.toLowerCase());if(node.tagName==='A'){const href=node.getAttribute('href')||'';if(/^(https?:|mailto:)/i.test(href))el.setAttribute('href',href);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer');}if(node.tagName==='IMG'){const src=node.getAttribute('src')||'';if(!/^data:image\/(png|jpeg|gif|webp);base64,/i.test(src))return document.createDocumentFragment();el.setAttribute('src',src);el.setAttribute('alt',(node.getAttribute('alt')||'Image').slice(0,200));el.setAttribute('loading','lazy');}const style=safeStyle(node.getAttribute('style'));if(style)el.setAttribute('style',style);[...node.childNodes].forEach(child=>el.append(cleanNode(child)));return el;};const result=document.createElement('div');[...parsed.body.childNodes].forEach(n=>result.append(cleanNode(n)));return result.innerHTML;}

